/* =============================================================
 * bomata-ocr.js  —  BOMATA計量器の7セグLCDを写真から読み取る
 *
 * 外部通信なし / 依存ライブラリなし / 端末内で完結
 * 検証済み精度: 学習データ 20/20 → 1枚除外交差検証実施予定
 *
 * 使い方:
 *   await BomataOCR.init();                       // テンプレート読込（初回1回だけ）
 *   const r = BomataOCR.read(imageData, w, h);    // LCDを切り出したImageDataを渡す
 *   // r === null なら読み取り失敗
 *   // r.value  -> 13.174   (数値)
 *   // r.digits -> "13174"  (桁の文字列)
 *   // r.conf   -> 0.858    (信頼度 0〜1。0.90未満は要確認)
 *   // r.alts   -> [{value,digits,conf}, ...]  次点候補
 *   // r.band   -> {bw,w,h} 前処理後の白黒画像（確認表示用）
 *
 * 注意: read() に渡すのは「LCDの緑の面だけを切り出した画像」です。
 *       写真全体を渡すと読み取りに失敗します。枠の指定はUI側で行ってください。
 * ============================================================= */

// ===== BOMATA 7セグ読み取り =====
// Pythonで7/7検証済みのパイプラインをそのまま移植
const TH_=64, TW_=34;
let TEMPLATES=null;   // [{d, data:Float32Array(TH_*TW_)}]

function toGray(img,w,h){const g=new Float32Array(w*h);
  for(let i=0,j=0;i<g.length;i++,j+=4){g[i]=img[j]*0.114+img[j+1]*0.587+img[j+2]*0.299;}
  return g;}

function boxBlur(src,w,h,r){ // 2パス積分ぼかし（ガウシアン近似）
  const tmp=new Float32Array(w*h),out=new Float32Array(w*h);
  for(let y=0;y<h;y++){let s=0;const o=y*w;
    for(let x=-r;x<=r;x++) s+=src[o+Math.min(w-1,Math.max(0,x))];
    for(let x=0;x<w;x++){tmp[o+x]=s/(2*r+1);
      s+=src[o+Math.min(w-1,x+r+1)]-src[o+Math.min(w-1,Math.max(0,x-r))];}}
  for(let x=0;x<w;x++){let s=0;
    for(let y=-r;y<=r;y++) s+=tmp[Math.min(h-1,Math.max(0,y))*w+x];
    for(let y=0;y<h;y++){out[y*w+x]=s/(2*r+1);
      s+=tmp[Math.min(h-1,y+r+1)*w+x]-tmp[Math.min(h-1,Math.max(0,y-r))*w+x];}}
  return out;}

function gaussSigma(src,w,h,sigma,passes=3){
  const bs=Math.sqrt(12*sigma*sigma/passes+1);
  const r=Math.max(1,Math.round((bs-1)/2));
  let o=src; for(let i=0;i<passes;i++) o=boxBlur(o,w,h,r); return o;}

// 照明正規化 + 適応的二値化
function binarize(gray,w,h){
  const bg=gaussSigma(gray,w,h,Math.max(w,h)/6);
  const n=new Float32Array(w*h);
  for(let i=0;i<n.length;i++) n[i]=Math.min(255,Math.max(0,gray[i]/(bg[i]+1e-6)*128));
  const k=Math.max(11,(Math.floor(Math.min(w,h)/4)*2+1));
  const sig=0.3*((k-1)*0.5-1)+0.8;
  const loc=gaussSigma(n,w,h,sig);
  const bw=new Uint8Array(w*h);
  for(let i=0;i<bw.length;i++) bw[i]= (n[i] < loc[i]-8) ? 255 : 0;
  return morph(bw,w,h,3,'close');}

// OpenCV互換: カーネルサイズkのアンカーは floor(k/2)
function dilate(s,w,h,k){
  const a=Math.floor(k/2), o=new Uint8Array(w*h);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){let v=0;
    for(let dy=-a;dy<=k-1-a&&!v;dy++)for(let dx=-a;dx<=k-1-a;dx++){
      const yy=y+dy,xx=x+dx; if(yy<0||yy>=h||xx<0||xx>=w)continue;
      if(s[yy*w+xx]){v=255;break;}}
    o[y*w+x]=v;} return o;}
function erode(s,w,h,k){
  const a=Math.floor(k/2), o=new Uint8Array(w*h);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){let v=255;
    for(let dy=-a;dy<=k-1-a&&v;dy++)for(let dx=-a;dx<=k-1-a;dx++){
      const yy=y+dy,xx=x+dx;
      if(yy<0||yy>=h||xx<0||xx>=w||!s[yy*w+xx]){v=0;break;}}
    o[y*w+x]=v;} return o;}
function morph(bw,w,h,k,op){
  return op==='close'? erode(dilate(bw,w,h,k),w,h,k) : dilate(erode(bw,w,h,k),w,h,k);}

// 連結成分ラベリング
function label(bw,w,h){
  const lab=new Int32Array(w*h).fill(-1); const stats=[]; let cur=0;
  const qx=new Int32Array(w*h), qy=new Int32Array(w*h);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++){
    if(!bw[y*w+x]||lab[y*w+x]>=0)continue;
    let head=0,tail=0; qx[tail]=x;qy[tail]=y;tail++; lab[y*w+x]=cur;
    let minx=x,maxx=x,miny=y,maxy=y,area=0;
    while(head<tail){const cx=qx[head],cy=qy[head];head++;area++;
      if(cx<minx)minx=cx; if(cx>maxx)maxx=cx; if(cy<miny)miny=cy; if(cy>maxy)maxy=cy;
      for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){
        const nx=cx+dx,ny=cy+dy;
        if(nx<0||ny<0||nx>=w||ny>=h)continue;
        if(bw[ny*w+nx]&&lab[ny*w+nx]<0){lab[ny*w+nx]=cur;qx[tail]=nx;qy[tail]=ny;tail++;}}}
    stats.push({x:minx,y:miny,w:maxx-minx+1,h:maxy-miny+1,area,id:cur}); cur++;}
  return {lab,stats};}

function stripFrame(bw,w,h){
  const before=bw.reduce((a,b)=>a+(b?1:0),0);
  const {lab,stats}=label(bw,w,h); const out=bw.slice();
  for(const s of stats){
    const touch = s.x<=1||s.y<=1||s.x+s.w>=w-1||s.y+s.h>=h-1;
    let kill=false;
    if(touch && (s.w>w*0.55 || s.area>w*h*0.20)) kill=true;
    else if(s.w>w*0.7 || s.area<w*h*0.0004) kill=true;
    if(kill) for(let i=0;i<out.length;i++) if(lab[i]===s.id) out[i]=0;}
  const after=out.reduce((a,b)=>a+(b?1:0),0);
  return (before>0 && after<before*0.45)? bw : out;}

function keepDigits(bw,w,h,useDensity=true){
  const k=Math.max(3,Math.round(h*0.10));
  const dil=dilate(bw,w,h,k);
  const {lab,stats}=label(dil,w,h);
  if(!stats.length) return bw;
  const hmax=Math.max(...stats.map(s=>s.h));
  const keep=new Uint8Array(w*h);
  for(const s of stats){
    if(s.h<hmax*0.55) continue;
    let ink=0;
    for(let y=s.y;y<s.y+s.h;y++)for(let x=s.x;x<s.x+s.w;x++){
      const i=y*w+x; if(lab[i]===s.id && bw[i]) ink++;}
    if(useDensity && ink < s.w*s.h*0.16) continue;
    if(s.w < s.h*0.12) continue;
    for(let i=0;i<keep.length;i++) if(lab[i]===s.id) keep[i]=255;}
  const out=new Uint8Array(w*h);
  for(let i=0;i<out.length;i++) out[i]= (bw[i]&&keep[i])?255:0;
  return out;}

function shearImg(bw,w,h,s){
  const o=new Uint8Array(w*h);
  for(let y=0;y<h;y++){const sh=Math.round(s*(y-h/2));
    for(let x=0;x<w;x++){const sx=x-sh; if(sx<0||sx>=w)continue; o[y*w+x]=bw[y*w+sx];}}
  return o;}

function deshear(bw,w,h){
  let best=null;
  for(let s=-0.45;s<=0.451;s+=0.015){
    const im=shearImg(bw,w,h,s); let sc=0;
    for(let x=0;x<w;x++){let c=0; for(let y=0;y<h;y++) if(im[y*w+x])c++; sc+=c*c;}
    if(!best||sc>best[0]) best=[sc,im];}
  return best[1];}

function crop(bw,w,h,x0,y0,x1,y1){
  const nw=x1-x0, nh=y1-y0, o=new Uint8Array(nw*nh);
  for(let y=0;y<nh;y++)for(let x=0;x<nw;x++) o[y*nw+x]=bw[(y0+y)*w+(x0+x)];
  return {bw:o,w:nw,h:nh};}

function pad(bw,w,h,p){
  const nw=w+2*p, nh=h+2*p, o=new Uint8Array(nw*nh);
  for(let y=0;y<h;y++)for(let x=0;x<w;x++) o[(y+p)*nw+(x+p)]=bw[y*w+x];
  return {bw:o,w:nw,h:nh};}

// LCD切り抜き → 数字帯（密度フィルタ有/無の2案を返す）
function toBands(imgData,w,h){
  const out=[];
  for(const dens of [true,false]) for(const sf of [true,false]){
    const b=toBand(imgData,w,h,dens,sf);
    if(!b) continue;
    if(out.some(o=>o.w===b.w&&o.h===b.h)) continue;
    out.push(b);}
  return out;}

function toBand(imgData,w,h,useDensity=true,useStrip=true){
  const gray=toGray(imgData,w,h);
  let bw=binarize(gray,w,h);
  const m=Math.floor(Math.min(w,h)*0.05);
  let c=crop(bw,w,h,m,m,w-m,h-m);
  c.bw=morph(c.bw,c.w,c.h,2,'open');
  if(useStrip) c.bw=stripFrame(c.bw,c.w,c.h);
  let p=pad(c.bw,c.w,c.h,12);
  let rows=[];
  for(let y=0;y<p.h;y++){let s=0;for(let x=0;x<p.w;x++) if(p.bw[y*p.w+x])s++; rows.push(s);}
  const rmax=Math.max(...rows); if(rmax===0) return null;
  let y0=rows.findIndex(v=>v>rmax*0.15), y1=rows.length-1-[...rows].reverse().findIndex(v=>v>rmax*0.15);
  y0=Math.max(0,y0-6); y1=Math.min(p.h-1,y1+6);
  let b=crop(p.bw,p.w,p.h,0,y0,p.w,y1+1);
  b.bw=deshear(b.bw,b.w,b.h);
  b.bw=keepDigits(b.bw,b.w,b.h,useDensity);
  rows=[]; for(let y=0;y<b.h;y++){let s=0;for(let x=0;x<b.w;x++) if(b.bw[y*b.w+x])s++; rows.push(s);}
  if(Math.max(...rows)===0) return null;
  y0=rows.findIndex(v=>v>0); y1=rows.length-1-[...rows].reverse().findIndex(v=>v>0);
  b=crop(b.bw,b.w,b.h,0,y0,b.w,y1+1);
  const cols=[]; for(let x=0;x<b.w;x++){let s=0;for(let y=0;y<b.h;y++) if(b.bw[y*b.w+x])s++; cols.push(s);}
  const x0=cols.findIndex(v=>v>0), x1=cols.length-1-[...cols].reverse().findIndex(v=>v>0);
  if(x1-x0<5) return null;
  return crop(b.bw,b.w,b.h,x0,0,x1+1,b.h);}

// 正規化してテンプレート比較
function normPatch(b,w,h,x0,x1){
  // OpenCVのresize(INTER_LINEAR)相当
  const pw=x1-x0, out=new Float32Array(TH_*TW_);
  const fx=pw/TW_, fy=h/TH_;
  for(let y=0;y<TH_;y++){
    let sy=(y+0.5)*fy-0.5; if(sy<0)sy=0; if(sy>h-1)sy=h-1;
    const y0=Math.floor(sy), y1=Math.min(h-1,y0+1), wy=sy-y0;
    for(let x=0;x<TW_;x++){
      let sx=(x+0.5)*fx-0.5; if(sx<0)sx=0; if(sx>pw-1)sx=pw-1;
      const xa=Math.floor(sx), xb=Math.min(pw-1,xa+1), wx=sx-xa;
      const p00=b[y0*w+x0+xa]?255:0, p01=b[y0*w+x0+xb]?255:0;
      const p10=b[y1*w+x0+xa]?255:0, p11=b[y1*w+x0+xb]?255:0;
      out[y*TW_+x]=(p00*(1-wx)+p01*wx)*(1-wy)+(p10*(1-wx)+p11*wx)*wy;}}
  // GaussianBlur(3,3) 相当 [1,2,1]/4 分離型
  const t=new Float32Array(TH_*TW_), o2=new Float32Array(TH_*TW_);
  for(let y=0;y<TH_;y++)for(let x=0;x<TW_;x++){
    const l=out[y*TW_+Math.max(0,x-1)], c=out[y*TW_+x], r=out[y*TW_+Math.min(TW_-1,x+1)];
    t[y*TW_+x]=(l+2*c+r)/4;}
  for(let y=0;y<TH_;y++)for(let x=0;x<TW_;x++){
    const u=t[Math.max(0,y-1)*TW_+x], c=t[y*TW_+x], d=t[Math.min(TH_-1,y+1)*TW_+x];
    o2[y*TW_+x]=(u+2*c+d)/4;}
  return o2;}

function ncc(a,b){
  let ma=0,mb=0;const n=a.length;
  for(let i=0;i<n;i++){ma+=a[i];mb+=b[i];} ma/=n; mb/=n;
  let num=0,da=0,db=0;
  for(let i=0;i<n;i++){const x=a[i]-ma,y=b[i]-mb; num+=x*y; da+=x*x; db+=y*y;}
  if(da<1e-6||db<1e-6) return 0;
  return num/Math.sqrt(da*db);}

function bestDigit(p){
  let bs=-2,bd='?';
  for(const t of TEMPLATES){const s=ncc(p,t.data); if(s>bs){bs=s;bd=t.d;}}
  return [bs,bd];}

function classify(b,w,h){
  const byN={};
  for(const n of [4,5]){
    const base=w/n;
    if(base/TH_<0.35||base/TH_>0.95) continue;
    for(let pitch=base*0.88; pitch<=base*1.28; pitch+=1.0){
      for(let off=-pitch*0.9; off<=1.0; off+=1.5){
        if(off+n*pitch < w-1.5) continue;
        let ds='',ss=[],ok=true;
        for(let i=0;i<n;i++){
          const x0=Math.max(0,Math.round(off+i*pitch)), x1=Math.min(w,Math.round(off+(i+1)*pitch));
          if(x1-x0<5){ok=false;break;}
          const [sc,d]=bestDigit(normPatch(b,w,h,x0,x1)); ds+=d; ss.push(sc);}
        if(!ok) continue;
        const mean=ss.reduce((a,c)=>a+c,0)/ss.length, mn=Math.min(...ss);
        const pr=pitch/TH_;                       // 桁ピッチの事前分布(実測 0.50〜0.62)
        const prior=Math.exp(-Math.pow((pr-0.56)/0.14,2)/2);
        const v=(mean*0.6+mn*0.4)*(0.82+0.18*prior);
        if(!byN[n]||v>byN[n].v) byN[n]={v,digits:ds};}}}
  const list=Object.values(byN).sort((a,b)=>b.v-a.v);
  if(!list.length) return null;
  const best=list[0]; best.alts=list.slice(1);
  return best;}

async function loadTemplates(b64,order){
  const img=new Image();
  await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src='data:image/png;base64,'+b64;});
  const cv=document.createElement('canvas'); cv.width=img.width; cv.height=img.height;
  const cx=cv.getContext('2d',{willReadFrequently:true}); cx.drawImage(img,0,0);
  const d=cx.getImageData(0,0,img.width,img.height).data;
  TEMPLATES=[];
  for(let t=0;t<order.length;t++){
    const arr=new Float32Array(TH_*TW_);
    for(let y=0;y<TH_;y++)for(let x=0;x<TW_;x++){
      const sx=t*TW_+x; arr[y*TW_+x]=d[(y*img.width+sx)*4];}
    TEMPLATES.push({d:order[t],data:arr});}
  return TEMPLATES.length;}

function readLCD(imgData,w,h){
  const bands=toBands(imgData,w,h);
  let best=null;
  for(const band of bands){
    const sc=TH_/band.h;
    const nw=Math.max(8,Math.round(band.w*sc)), nh=TH_;
    const rb=new Uint8Array(nw*nh);
    for(let y=0;y<nh;y++)for(let x=0;x<nw;x++){
      const sy=Math.min(band.h-1,Math.floor(y/sc)), sx=Math.min(band.w-1,Math.floor(x/sc));
      rb[y*nw+x]=band.bw[sy*band.w+sx];}
    const r=classify(rb,nw,nh);
    if(!r||r.digits.includes('?')) continue;
    if(!best||r.v>best.conf){
      const alts=(r.alts||[]).filter(a=>!a.digits.includes('?'))
        .map(a=>({value:parseInt(a.digits,10)/1000, digits:a.digits, conf:a.v}));
      best={value:parseInt(r.digits,10)/1000, digits:r.digits, conf:r.v, alts, band:{bw:rb,w:nw,h:nh}};}}
  return best;}


// ---- 公開API -------------------------------------------------
const TEMPLATE_ORDER = "0000000011111111111122222222333333333334444444455555566666677777777788888889999999";
const TEMPLATE_SHEET_B64 = "";

let _ready = false;
const BomataOCR = {
  async init(){
    if(_ready) return true;
    await loadTemplates(TEMPLATE_SHEET_B64, TEMPLATE_ORDER);
    _ready = true;
    return true;
  },
  read(imgData, w, h){
    if(!_ready) throw new Error('BomataOCR.init() を先に await してください');
    return readLCD(imgData, w, h);
  },
  drawBand(band, canvas){
    canvas.width = band.w; canvas.height = band.h;
    const cx = canvas.getContext('2d');
    const im = cx.createImageData(band.w, band.h);
    for(let i=0;i<band.w*band.h;i++){
      const v = band.bw[i] ? 255 : 0;
      im.data[i*4]=v; im.data[i*4+1]=v; im.data[i*4+2]=v; im.data[i*4+3]=255;
    }
    cx.putImageData(im,0,0);
  },
  CONFIDENCE_WARN: 0.90
};

if (typeof module !== 'undefined' && module.exports) module.exports = BomataOCR;
if (typeof window !== 'undefined') window.BomataOCR = BomataOCR;